/**
 * Dev-only sample boot data: `viewer.html?fixture=<name>` (see FIXTURE_NAMES).
 * main.tsx imports this behind `import.meta.env.DEV`, so it is dropped from production
 * builds. It writes the same DOM the worker will, so the real boot path is exercised.
 * Media files come from web/fixtures/ (generated by `npm run fixtures`), which the dev
 * server serves at /fixtures/.
 */

import {
  JSON_SAMPLE,
  manyLines,
  MARKDOWN_SAMPLE,
  peaksUrl,
  PLAIN_SAMPLE,
  PYTHON_SAMPLE,
  recordClip,
  RUST_SAMPLE,
  textUrl,
  TYPESCRIPT_SAMPLE,
} from './fixtureMedia';
import type { FileData } from './types';

export const FIXTURE_NAMES = [
  'image',
  'file',
  'pdf',
  'pdf-password',
  'missing',
  'unavailable',
  'home',
  'convert',
  'album-grid',
  'album-list',
  'album-tracklist',
  'locked',
  'locked-short',
  'locked-expired',
  'locked-album',
  'private',
  // Milestone 3
  'video',
  'video-unplayable',
  'processing',
  'audio-cover',
  'audio-waveform',
  'audio-unplayable',
  'image-heic',
  'text',
  'text-typescript',
  'text-rust',
  'text-json',
  'text-markdown',
  'text-plain',
  'text-huge',
  'text-lines',
  'album-huge',
] as const;
export type FixtureName = (typeof FIXTURE_NAMES)[number];

const HOUR = 60 * 60 * 1000;
const DAY = 24 * HOUR;
/** Payload times are epoch seconds (contract §4). */
const secs = (ms: number) => Math.floor(ms / 1000);

interface Fixture {
  page?: string;
  state?: string;
  /** undefined: no script tag. null: the literal `null` payload. */
  file?: FileData | Record<string, unknown> | null;
  album?: Record<string, unknown>;
}

const fx = (name: string) => `${location.origin}/fixtures/${name}`;

/**
 * Previews. In production they're `https://cdn.files.gg/previews/<kind>/<vanity>.<ext>?v=…`
 * (contract §3), signed when the file is protected; here they must load from the dev
 * server, so they're the local fixture files with a `?v=` like the real ones. URLs that
 * are never fetched in dev (collages, the too-large album's ZIP) use the real shape.
 */
const asset = (name: string, width?: number, height?: number) => ({ url: `${fx(name)}?v=1795600000`, width, height });
const CDN = 'https://cdn.files.gg';

interface FixtureMedia {
  /** A playable WebM recorded in the browser, or null (then a WAV stands in). */
  clip: string | null;
}

